RSpec.describe Timekeeping::Gateway do
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
  end

  # "A missing row or an unknown owner also refuses (fail closed). It never falls back to legacy and never answers 404."
  # The database check constraint refuses an unknown owner, so the value reaches the gateway through its injected reader.
  it "refuses a create for an unknown owner value instead of falling back to the legacy table" do
    unknown_owner = TimekeepingOwnership.new(id: TimekeepingOwnership::SINGLETON_ID, owner: "elsewhere", generation: 1,
                                             monolith_store: "legacy", handoff_step: nil)
    context = Timekeeping::WriteContext.new(company:, actor: admin, actor_kind: "user", request_id: "req-unknown-owner")
    gateway = described_class.new(context:, ownership_reader: -> { unknown_owner })

    expect do
      expect do
        gateway.create(user: admin, project:, attributes: {
          duration: 30, work_date: Date.current, note: "must not land", bill_status: "unbilled"
        })
      end.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end.not_to change(TimesheetEntry, :count)
  end
end

RSpec.describe Timekeeping::Gateway do
  let(:gw_company) { create(:company) }
  let(:gw_admin) do
    create(:user, current_workspace_id: gw_company.id).tap do |user|
      create(:employment, company: gw_company, user:)
      user.add_role :admin, gw_company
    end
  end
  let(:gw_project) { create(:project, billable: true, client: create(:client, company: gw_company)) }
  let(:gw_base_url) { "http://timekeeping.test" }
  let(:gw_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:gw_local_owner) { Timekeeping::FakeLocalOwner.new }
  let(:gw_context) do
    Timekeeping::WriteContext.new(company: gw_company, actor: gw_admin, actor_kind: "user", request_id: "req-gateway-1")
  end
  let(:gw_attributes) { { duration: 30, work_date: Date.current, note: "gateway", bill_status: "unbilled" } }
  let(:gw_allow_all) { ->(_entry) { } }

  before { route_timekeeping_to_fake(gw_fake, base_url: gw_base_url) }

  def gw_ownership
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
  end

  def gw_gateway(**options)
    described_class.new(
      context: gw_context, local_owner: gw_local_owner,
      write_client: Timekeeping::EntryWriteClient.new(base_url: gw_base_url),
      read_client: Timekeeping::EntryApiClient.new(base_url: gw_base_url),
      **options
    )
  end

  # Collects every EntryWriteRefused event the block reports.
  def gw_refusal_events
    events = []
    subscriber = Object.new
    subscriber.define_singleton_method(:emit) do |event|
      events << event if event[:name] == "Timekeeping::EntryWriteRefused"
    end
    Rails.event.subscribe(subscriber)
    begin
      yield
    ensure
      Rails.event.unsubscribe(subscriber)
    end
    events
  end

  def gw_with_key(&block)
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem, &block)
  end

  def gw_expect_one_refusal(events, reason)
    expect(events.size).to eq(1)
    expect(events.first[:payload].to_h[:data]).to eq(
      reason:, company_id: gw_company.id, request_id: "req-gateway-1", actor_kind: "user"
    )
  end

  it "refuses create and update while handoff_step is set, changing nothing and emitting one event each" do
    entry = create(:timesheet_entry, user: gw_admin, project: gw_project, note: "kept")
    gw_ownership.update_columns(handoff_step: "close_admission")

    create_events = gw_refusal_events do
      expect { gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes) }
        .to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end
    update_events = gw_refusal_events do
      expect do
        gw_gateway.update(entry_id: entry.id, project: gw_project, attributes: { note: "changed" }, authorize: gw_allow_all)
      end.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end

    expect(TimesheetEntry.count).to eq(1)
    expect(entry.reload.note).to eq("kept")
    expect(gw_fake.requests).to be_empty
    expect(gw_local_owner.calls).to be_empty
    gw_expect_one_refusal(create_events, "ownership_moving")
    gw_expect_one_refusal(update_events, "ownership_moving")
  end

  it "refuses a destroy when the ownership row is missing instead of answering not found" do
    entry = create(:timesheet_entry, user: gw_admin, project: gw_project)
    TimekeepingOwnership.delete_all

    events = gw_refusal_events do
      expect { gw_gateway.destroy(entry_id: entry.id, authorize: gw_allow_all) }
        .to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end

    expect(entry.reload.discarded_at).to be_nil
    expect(gw_fake.requests).to be_empty
    gw_expect_one_refusal(events, "ownership_moving")
  end

  # The database check constraint refuses an unknown store, so it reaches the gateway through its injected reader.
  it "refuses a create for an unknown monolith store" do
    unknown_store = TimekeepingOwnership.new(id: TimekeepingOwnership::SINGLETON_ID, owner: "monolith", generation: 1,
                                             monolith_store: "elsewhere", handoff_step: nil)

    events = gw_refusal_events do
      expect do
        gw_gateway(ownership_reader: -> { unknown_store }).create(user: gw_admin, project: gw_project,
                                                                  attributes: gw_attributes)
      end.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end

    expect(TimesheetEntry.count).to eq(0)
    expect(gw_local_owner.calls).to be_empty
    gw_expect_one_refusal(events, "ownership_moving")
  end

  it "routes a legacy store at a raised generation to the legacy table and forwards nothing" do
    gw_ownership.update_columns(generation: 2)

    entry = gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes)

    expect(entry).to be_persisted
    expect(TimesheetEntry.where(id: entry.id, user_id: gw_admin.id)).to exist
    expect(gw_fake.requests).to be_empty
    expect(gw_local_owner.calls).to be_empty
  end

  it "puts back the writer mark of a caller's transaction it joined" do
    connection = ActiveRecord::Base.connection
    seen_after = ActiveRecord::Base.transaction do
      connection.execute("SET LOCAL miru.writer = 'caller_mark'")
      gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes)
      connection.select_value("SELECT current_setting('miru.writer', true)")
    end

    expect(seen_after).to eq("caller_mark")
  end

  it "puts back the caller's writer mark when the legacy write fails, keeping the write's own error" do
    connection = ActiveRecord::Base.connection
    raised = nil
    seen_after = ActiveRecord::Base.transaction do
      connection.execute("SET LOCAL miru.writer = 'caller_mark'")
      begin
        gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes.merge(duration: -5))
      rescue ActiveRecord::RecordInvalid => error
        raised = error
      end
      connection.select_value("SELECT current_setting('miru.writer', true)")
    end

    expect(raised).to be_a(ActiveRecord::RecordInvalid)
    expect(seen_after).to eq("caller_mark")
  end

  def gw_own_by_timekeeping(project = gw_project)
    gw_ownership.update_columns(owner: "timekeeping", generation: 2)
    gw_fake.generation = 2
    gw_fake.register_company(id: gw_company.id, edit_days: gw_company.timesheet_edit_days)
    gw_fake.register_user(id: gw_admin.id, company_id: gw_company.id, role: "admin")
    gw_fake.register_project(id: project.id, company_id: gw_company.id)
  end

  it "refuses a forwarded create already marked billed before anything is sent, as the legacy store does" do
    gw_own_by_timekeeping

    expect do
      gw_with_key do
        gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes.merge(bill_status: "billed"))
      end
    end.to raise_error(ActiveRecord::RecordInvalid)
    expect(gw_fake.requests).to be_empty
  end

  it "forwards the project's billing default when a create leaves bill_status out" do
    non_billable = create(:project, billable: false, client: create(:client, company: gw_company))
    gw_own_by_timekeeping(non_billable)
    gw_fake.register_project(id: gw_project.id, company_id: gw_company.id)
    attributes = gw_attributes.except(:bill_status)

    # Two requests, so the two creates carry different Idempotency-Keys.
    second_context = Timekeeping::WriteContext.new(company: gw_company, actor: gw_admin, actor_kind: "user",
                                                   request_id: "req-gateway-2")
    second_gateway = described_class.new(
      context: second_context, write_client: Timekeeping::EntryWriteClient.new(base_url: gw_base_url),
      read_client: Timekeeping::EntryApiClient.new(base_url: gw_base_url)
    )
    gw_with_key do
      gw_gateway.create(user: gw_admin, project: non_billable, attributes:)
      second_gateway.create(user: gw_admin, project: gw_project, attributes:)
    end

    sent = gw_fake.requests.map { |request| request[:body]["bill_status"] }
    expect(sent).to eq(%w[non_billable unbilled])
  end

  it "raises StaleGeneration for a wrong expected generation, writing nothing and emitting one event" do
    events = gw_refusal_events do
      expect do
        gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes, expected_generation: 7)
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)
    end

    expect(TimesheetEntry.count).to eq(0)
    expect(gw_fake.requests).to be_empty
    gw_expect_one_refusal(events, "stale_generation")
  end

  it "counts Timekeeping's own stale_generation answer once and writes nothing locally" do
    gw_ownership.update_columns(owner: "timekeeping", generation: 2)
    gw_fake.register_company(id: gw_company.id, edit_days: gw_company.timesheet_edit_days)
    gw_fake.register_user(id: gw_admin.id, company_id: gw_company.id, role: "admin")
    gw_fake.register_project(id: gw_project.id, company_id: gw_company.id)
    gw_fake.generation = 3

    events = gw_refusal_events do
      expect do
        gw_with_key { gw_gateway.create(user: gw_admin, project: gw_project, attributes: gw_attributes) }
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)
    end

    expect(gw_fake.requests.size).to eq(1)
    expect(gw_fake.requests.first[:headers]["Ownership-Generation"]).to eq("2")
    expect(TimesheetEntry.count).to eq(0)
    gw_expect_one_refusal(events, "stale_generation")
  end

  it "hands a prepared update and destroy to the local owner as a lookup then the write, and nothing else" do
    gw_ownership.update_columns(monolith_store: "prepared", generation: 2)
    stored = TimesheetEntry.new(id: 4242, company_id: gw_company.id, user: gw_admin, project: gw_project,
                                work_date: Date.current, duration: 30, bill_status: "unbilled", note: "prepared")
    local_owner = Timekeeping::FakeLocalOwner.new(entries: { 4242 => stored })
    authorized = []

    expect do
      gw_gateway(local_owner:).update(entry_id: 4242, project: gw_project, attributes: { note: "edited" },
                                      authorize: ->(entry) { authorized << entry })
      gw_gateway(local_owner:).destroy(entry_id: 4242, authorize: ->(entry) { authorized << entry })
    end.not_to change(TimesheetEntry, :count)

    expect(local_owner.calls.pluck(:method)).to eq(%i[find_entry update_entry find_entry destroy_entry])
    expect(authorized).to eq([stored, stored])
    expect(gw_fake.requests).to be_empty
    expect(Timekeeping::LocalEntry.count).to eq(0)
  end
end

RSpec.describe "Timekeeping::Gateway refusal types" do
  it "refuses entry writes with a subclass of the billing refusal, so existing 503 handling catches it" do
    expect(Timekeeping::Gateway::OwnershipMoving.new).to be_a(Timekeeping::BillingFence::OwnershipMoving)
    expect(Timekeeping::Gateway::OwnershipMoving.new).not_to be_a(ActiveRecord::RecordInvalid)
    expect(Timekeeping::Gateway::OwnershipMoving.new.message).to eq("ownership_moving")
  end

  it "raises a stale generation refusal that is not a validation error" do
    expect(Timekeeping::Gateway::StaleGeneration.new).not_to be_a(ActiveRecord::RecordInvalid)
    expect(Timekeeping::Gateway::StaleGeneration.new.message).to eq("stale_generation")
  end

  it "refuses every local-owner call by default as a retryable ownership move" do
    local_owner = Timekeeping::Gateway::UnavailableLocalOwner.new

    %i[find_entry create_entry update_entry destroy_entry].each do |method|
      expect { local_owner.public_send(method, context: nil) }.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end
  end
end
